#include <stdio.h>

/* teste do desafio eco-de-nome — counter_protocol (03-tdd 3.9.3).
   Quem DIGITA e o teste: fopen/fprintf escrevem num arquivo o que o aluno
   digitaria, o freopen troca o stdin por esse arquivo, e a captura do
   stdout acontece dentro do proprio cenario (freopen + fflush, sem
   fclose no stdout). Dois cenarios, dois nomes diferentes: a saida nao
   pode vir de um texto fixo no codigo. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void ecoDeNome(void);

SM_TEST(o_eco_de_ana) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "Ana\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    ecoDeNome();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o eco de Ana", linha, "oi, Ana!\n",
              "a palavra digitada entrou na caixa e saiu pelo buraco %s");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na linha da saudacao: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(o_eco_de_bruno) {
    FILE *digitado = fopen("sm_entrada_2.tmp", "w");
    fprintf(digitado, "Bruno\n");
    fclose(digitado);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    ecoDeNome();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o eco de Bruno", linha, "oi, Bruno!\n",
              "outro nome digitado, outra saida: o texto vem da leitura, nao do codigo");
    fclose(f);
}

